code.cpp:
class Solution {
public:
    bool canArrange(vector<int>& arr, int k) {
        vector<int> freq(k, 0);
        for (int x : arr) {
            int r = ((x % k) + k) % k;
            freq[r]++;
        }
        if (freq[0] % 2 != 0) return false;
        for (int i = 1; i <= k / 2; i++) {
            if (i == k - i) {
                if (freq[i] % 2 != 0) return false;
            } else {
                if (freq[i] != freq[k - i]) return false;
            }
        }
        return true;
    }
};
